import {practicalSteps,temperatureRows,practicalThermalCorrect,bondCases,bondAccount,bondCorrect} from './thermal-models.js?v=20261023-physicscomplete01';
import {showThermal} from './thermal-scenes.js?v=20261023-physicscomplete01';
const field=(id,label)=>`<label class="field-label" for="${id}">${label}</label><input class="lab-input" id="${id}" type="number" step="any">`;
const select=(id,label,opts)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${opts.map(([v,label])=>`<option value="${v}">${label}</option>`).join('')}</select>`;
export function mountThermalWidget(l,p,root,{save,done,feedback}){const w=p.widget;w.task??=0;w.answers??={};w.passed??=[];const bonds=l.widget==='thermal-bonds',tasks=bonds?bondCases:practicalSteps,i=w.task%tasks.length,t=tasks[i],a=w.answers[t.id]??={};w.answers[t.id]=a;const $=s=>root.querySelector(s),valid=()=>bonds?bondCorrect(t,a):practicalThermalCorrect(t,a);
 let body='',keys=[];if(bonds){body=`<p><b>${i+1} / 3 · ${t.equation}</b></p><p>Supplied bond energies (kJ/mol): ${t.rows.map(r=>`${r.label} ${r.energy}`).join('; ')}. Count bonds for the balanced equation.</p><div class="thermal-fields">`+t.rows.map(r=>'<div>'+field('thermal-'+r.key,`${r.side==='break'?'Break':'Form'} ${r.label}`)+'</div>').join('')+'</div><div class="thermal-fields">'+[['broken','Taken in'],['formed','Released'],['overall','Overall']].map(([k,label])=>'<div>'+field('thermal-'+k,label+' / kJ/mol')+'</div>').join('')+'</div>'+select('thermal-kind','Reaction type',[['exo','Exothermic'],['endo','Endothermic'],['zero','No overall transfer']]);keys=[...t.rows.map(r=>r.key),'broken','formed','overall','kind'];}else{body=`<p><b>${i+1} / 3 · ${t.title}</b></p><p>${t.prompt}</p>`;if(t.id==='data'){body+='<div class="thermal-fields">'+temperatureRows.map((r,i)=>'<div>'+field('thermal-rise'+i,'Rise at '+r.concentration.toFixed(2)+' / °C')+'</div>').join('')+'</div>'+select('thermal-trend','Trend over this tested range',[['same','Same rise'],['increase','Rise increases with concentration'],['all','All reactions must follow this trend']]);keys=['rise0','rise1','rise2','trend'];}else{body+=t.fields.map(([id,label,opts])=>select('thermal-'+id,label,opts)).join('');keys=t.fields.map(f=>f[0]);}}
 root.innerHTML=body+`<button class="secondary" id="checkThermal">Check ${bonds?'account':'decision'}</button><button class="secondary" id="nextThermal">Next case →</button><p id="thermalProgress">${w.passed.length} / 3 correct</p>`;
 const draw=()=>showThermal(bonds?'bonds':t.id==='plan'?'apparatus':t.id,t,a,w.passed.includes(t.id)&&valid());keys.forEach(k=>{const el=$('#thermal-'+k);el.value=a[k]??'';el[el.tagName==='INPUT'?'oninput':'onchange']=e=>{a[k]=e.target.value;save();draw();};});draw();
 $('#checkThermal').onclick=()=>{if(!valid()){feedback(bonds?'Count each bond in every molecule, including coefficients. Multiply counts by supplied values. Overall = taken in − released; negative is exothermic.':t.id==='data'?'Use maximum minus initial for each row. Keep the conclusion within this reaction and concentration range.':t.id==='plan'?'Change concentration; compare temperature rise. Keep volumes, initial temperature and measurement conditions consistent.':'Investigate the unusual repeat and repeat the condition. Insulation and a lid reduce heat loss; they do not prove an exact value.',true);return;}if(!w.passed.includes(t.id))w.passed.push(t.id);save();draw();$('#thermalProgress').textContent=w.passed.length+' / 3 correct';feedback(bonds?'Correct: bond counts, both totals, signed change and reaction type agree.':'Correct: your decisions follow the controlled method and supplied evidence.');if(w.passed.length===3){p.widgetDone=true;save();done();}};
 $('#nextThermal').onclick=()=>{w.task=(i+1)%3;save();feedback('');mountThermalWidget(l,p,root,{save,done,feedback});};}
